function warmObjectThumbs(){const generation=++thumbGeneration,types=[...new Set(project.modules.map(m=>m.type))];function next(){if(generation!==thumbGeneration)return;const type=types.shift();if(!type)return;thumbs.set(type,scene.thumbnail(createModule(type)));for(const img of document.querySelectorAll('#object-list img')){const m=project.modules.find(m=>m.id===img.closest('[data-select]')?.dataset.select);if(m?.type===type)img.src=thumbs.get(type);}if(types.length)requestAnimationFrame(next);}requestAnimationFrame(next);}
