function addModule(type){if(project.modules.length>=60){toast('В одном проекте можно разместить до 60 модулей.');return;}const m=PRESETS.some(p=>p.id===type)?createPreset(type):createModule(type);const similar=project.modules.filter(x=>x.type!=='wall'&&x.visible);let free=false;for(let z=-project.room.depth/2+m.depth/2+10;z<=project.room.depth/2-m.depth/2;z+=Math.max(m.depth+100,650)){for(let x=-project.room.width/2+m.width/2+10;x<=project.room.width/2-m.width/2;x+=100){m.x=Math.round(x);m.z=Math.round(z);if(!conflicts({...project,modules:[...project.modules,m]}).overlaps.some(pair=>pair.includes(m.id))){free=true;break;}}if(free)break;}if(!free){m.x=0;m.z=0;}project.modules.push(m);selected=m.id;changed({rebuild:true});scene.select(selected);inspectorTab('module');showPanel('');toast(`${m.name} добавлен${free?'':'. Проверьте пересечения'}`);}
