function updateProperty(el,commit=true){const m=current();if(!m||m.locked)return;const k=el.dataset.prop,prior=m[k];if(el.type==='number'||el.type==='range'){if(el.value===''||!Number.isFinite(Number(el.value))){el.value=m[k];toast('Введите число в допустимом диапазоне');return;}const [min,max]=LIMITS[k];if(+el.value<min||+el.value>max)toast(`Допустимый диапазон: ${min}–${max}`);m[k]=Math.min(max,Math.max(min,+el.value));if(['shelves','drawers','doors','thickness'].includes(k))m[k]=Math.round(m[k]);}else if(el.type==='checkbox')m[k]=el.checked;else if(k==='thickness')m[k]=Number(el.value);else m[k]=el.value;if(['width','height','depth'].includes(k)&&assembly?.settings.coupled){const value=m[k];m[k]=prior;resizeCoupled(m,k,value);}if(k==='customColor'){m.front='custom';m.frontMaterial='';}if(['body','top'].includes(k))m[k+'Material']='';if(k==='handleColor')m.handleMaterial='';if(k==='name')m.name=m.name.trim()||CATALOG.find(c=>c.type===m.type).name;scene.updateModule(m);$('#open-value').textContent=m.open+'%';if(commit)changed();}
