function duplicate(){const m=current();if(!m)return;if(project.modules.length>=60){toast('Лимит: 60 модулей');return;}const copy={...structuredClone(m),id:createModule(m.type).id,name:m.name+' · копия',x:m.x+m.width+50,locked:false};snapPosition(copy,project,50);project.modules.push(copy);selected=copy.id;changed({rebuild:true});scene.select(selected);toast('Модуль скопирован');}
