$$('[data-room]').forEach(el=>{const applyRoom=()=>{const k=el.dataset.room;if(el.type==='number'){const n=Number(el.value);if(!Number.isFinite(n)||n<Number(el.min)||n>Number(el.max)){el.value=project.room[k];toast(`Допустимый диапазон: ${el.min}–${el.max} мм`);return;}if(project.room.vertices&&['width','depth'].includes(k)){const axis=k==='width'?'x':'z',v=project.room.vertices,values=v.map(p=>p[axis]),center=(Math.max(...values)+Math.min(...values))/2,ratio=n/project.room[k];for(const point of v)point[axis]=center+(point[axis]-center)*ratio;}project.room[k]=n;}else project.room[k]=el.type==='checkbox'?el.checked:el.value;if(k==='floorProfile'&&MATERIAL_BY_ID[project.room[k]])project.room.floorRoughness=MATERIAL_BY_ID[project.room[k]].roughness;if(k==='wallProfile'&&MATERIAL_BY_ID[project.room[k]]){project.room.wallRoughness=MATERIAL_BY_ID[project.room[k]].roughness;project.room.wallFinishes=[];}if(k==='backsplashProfile'&&project.room[k]&&project.room.backsplash==='none')project.room.backsplash='marble';if(['floor','floorColor'].includes(k))project.room.floorProfile='';if(['wall','leftWall','wallMaterial'].includes(k))project.room.wallProfile='';if(['backsplash','backsplashColor'].includes(k))project.room.backsplashProfile='';project.room=normalizeRoom(project.room);scene.buildRoom();changed();};el.onchange=applyRoom;el.oninput=()=>{if(el.type==='number'&&(el.value===''||!el.validity.valid))return;clearTimeout(propertyTimer);propertyTimer=setTimeout(applyRoom,280);};});
