function saveCopy(){const list=library();if(list.length>=20){toast('Уже сохранено 20 копий. Экспортируйте JSON или удалите ненужную копию.');return;}list.unshift({id:createModule('base').id,date:new Date().toISOString(),data:JSON.stringify(project)});try{localStorage.setItem(LIBRARY,JSON.stringify(list));saveCurrent();renderLibrary();toast('Копия проекта сохранена');}catch{toast('Недостаточно места. Экспортируйте JSON.');}}
$('#save-project').onclick=()=>{if(saveCurrent())toast('Проект сохранён на этом устройстве');};$('#save-copy').onclick=saveCopy;$('#projects-open').onclick=()=>{renderLibrary();$('#projects-dialog').showModal();};$('#project-library').onclick=e=>{const open=e.target.closest('[data-load-project]'),remove=e.target.closest('[data-remove-project]');if(open){try{project=parseProject(library().find(p=>p.id===open.dataset.loadProject).data);selected=project.modules[0]?.id||null;changed({rebuild:true});scene.select(selected);setView('3d');$('#projects-dialog').close();toast('Проект открыт');}catch{toast('Не удалось прочитать сохранённый проект');}}if(remove){const list=library().filter(p=>p.id!==remove.dataset.removeProject);try{localStorage.setItem(LIBRARY,JSON.stringify(list));renderLibrary();toast('Сохранённая копия удалена');}catch{toast('Не удалось удалить копию');}}};
$('#import-project').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('Файл слишком большой: максимум 3 МБ');const next=parseProject(await file.text());project=next;selected=project.modules[0]?.id||null;changed({rebuild:true});scene.select(selected);setView('3d');$('#import-error').textContent='';$('#projects-dialog').close();toast('Проект импортирован. Предыдущий можно вернуть через отмену.');}catch(err){$('#import-error').textContent=err.message;}e.target.value='';};
function download(data,name,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Файл подготовлен для скачивания');}
const fileName=()=>project.name.replace(/[<>:"/\\|?*\x00-\x1f]/g,'').slice(0,65)||'Batesto';
function png(){try{downloadPNG(scene.snapshot(),fileName()+'.png');toast('Изображение подготовлено для скачивания');}catch(err){toast('Не удалось сохранить изображение: '+err.message);}}
$('#export-open').onclick=()=>{$('#brief').value=makeBrief(project);$('#export-dialog').showModal();};$('#export-json').onclick=()=>download(JSON.stringify(project,null,2),fileName()+'.json','application/json');$('#export-csv').onclick=()=>download(makeCSV(project),fileName()+' — спецификация.csv','text/csv;charset=utf-8');$('#export-obj').onclick=()=>download(scene.exportOBJ(),fileName()+'.obj','text/plain');$('#export-png').onclick=png;$('#screenshot').onclick=png;
$('#copy-brief').onclick=async()=>{try{await navigator.clipboard.writeText($('#brief').value);toast('Текст скопирован. Вставьте его в чат с Вадимом.');}catch{$('#brief').select();toast('Выделенный текст можно скопировать через Ctrl+C.');}};
$('#warnings-open').onclick=()=>{const c=conflicts(project),byId=id=>project.modules.find(m=>m.id===id);$('#warnings-list').innerHTML=c.outside.map(id=>`<button class="warning-item" data-warning-select="${esc(id)}">За границей комнаты: ${esc(byId(id).name)} ↗</button>`).join('')+c.overlaps.map(([a,b])=>`<button class="warning-item" data-warning-select="${esc(a)}">Пересекаются: ${esc(byId(a).name)} и ${esc(byId(b).name)} ↗</button>`).join('')||'<p class="warnings-good">Пересечений и выхода за границы комнаты не обнаружено.</p>';$('#warnings-dialog').showModal();};$('#warnings-list').onclick=e=>{const b=e.target.closest('[data-warning-select]');if(b){$('#warnings-dialog').close();select(b.dataset.warningSelect,true);scene.focus();inspectorTab('module');}};
$('#help-open').onclick=()=>$('#help-dialog').showModal();$$('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
window.addEventListener('keydown',e=>{if(reviewMode||!ready||e.target.closest('input,textarea,select')||$('dialog[open]'))return;const cmd=e.ctrlKey||e.metaKey;if(scene.exploder.active&&['m','r','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Delete','Backspace'].includes(e.key))return;if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey?'redo':'undo');}else if(cmd&&e.key.toLowerCase()==='y'){e.preventDefault();historyStep('redo');}else if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();saveCurrent();toast('Проект сохранён');}else if(cmd&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}else if(e.key.toLowerCase()==='r')rotate();else if(e.key.toLowerCase()==='m')mode('move');else if(e.key.toLowerCase()==='v')mode('orbit');else if(e.key==='Escape'){select(null);showPanel('');}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const m=current();if(!m||m.locked)return;e.preventDefault();const step=e.shiftKey?10:Number($('#snap').value);if(e.key==='ArrowLeft')m.x-=step;if(e.key==='ArrowRight')m.x+=step;if(e.key==='ArrowUp')m.z-=step;if(e.key==='ArrowDown')m.z+=step;scene.updateModule(m);changed();}});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);saveCurrent();});
function failed(err){$('#loading').hidden=true;$('#scene-error').hidden=false;$('#scene-error-text').textContent=err.message.includes('контекст')?err.message:'Для редактора нужен WebGL 2. Попробуйте открыть страницу в актуальном Chrome или Edge с аппаратным ускорением. Сохранённый проект остаётся в браузере.';console.error(err);}
try{scene=new StudioScene($('#viewport'),{onReady:()=>{ready=true;},onError:failed,onSelect:id=>{select(id);},onMove:(id,x,z,step)=>{const m=project.modules.find(m=>m.id===id);m.x=Math.round(x);m.z=Math.round(z);snapPosition(m,project,step);},onMoveEnd:(id,x,z)=>{const m=project.modules.find(m=>m.id===id);if(m.x!==x||m.z!==z)changed();},onPart:id=>advanced?.selectPart(id),onContext:(x,y,id)=>advanced?.context(x,y,id),onSurface:key=>advanced?.surface(key),onPartMove:(id,partId,values)=>{const m=project.modules.find(m=>m.id===id);m.details||={};m.details[partId]={...m.details[partId],...values};scene.updateModule(m);renderInspector();},onResize:(id,axis,value,partId)=>{const m=project.modules.find(m=>m.id===id);if(partId){m.details||={};m.details[partId]||={};m.details[partId][axis]=value;}else m[axis]=value;scene.updateModule(m);renderInspector();},onResizeEnd:()=>changed()});if(ready){advanced=installAdvanced({scene,current,commit:changed,renderInspector,showPanel,inspectorTab,toast,mode,duplicate,remove,rotate});scene.setProject(project);materials=installMaterials({scene,current,getProject:()=>project,commit:changed,toast,advanced});$('#realism-toggle').onchange=e=>{scene.realism.enabled=e.target.checked;scene.dirty=true;};$('#photo-view').onclick=()=>{setView('3d');scene.photoView();};scene.realism.updateStatus();assembly=installAssembly({getProject:()=>project,current,commit:changed,scene,toast,renderInspector,selectPart:id=>advanced.selectPart(id)});hardware=installHardware({scene,current,advanced,commit:changed,toast});easy=installEasyUI({scene,current,advanced,assembly,materials,commit:changed,inspectorTab,showPanel,toast});installRoomPro({getProject:()=>project,commit:changed,scene,toast});installStudioUpgrades({scene,current,getProject:()=>project,advanced,easy,inspectorTab,showPanel,toast,select});business=installBusiness({getProject:()=>project,replaceProject,scene,toast,commit:changed});catalogUI=installCatalogLibrary({root:$('#catalog'),searchInput:$('#search'),categoryRoot:$('.category-tabs'),thumbnail:m=>scene.thumbnail(m),onAdd:addModule});scene.onTexturesReady=()=>{catalogUI?.refreshThumbnails();warmObjectThumbs();renderCatalog();renderObjects();};warmObjectThumbs();renderCatalog();renderObjects();renderSummary();scene.select(selected);renderInspector();renderHistory();setView('3d');$('#loading').hidden=true;$('#save-state').textContent=restored?'Восстановлен с устройства':'Изменения сохраняются автоматически';}}catch(err){failed(err);}

function replaceProject(raw){const next=parseProject(JSON.stringify(raw));project=next;selected=project.modules[0]?.id||null;changed({rebuild:true});}
const reviewBanner=document.createElement('div');reviewBanner.className='review-banner';reviewBanner.hidden=!reviewMode;reviewBanner.innerHTML='<span>Снимок для просмотра. Ваш рабочий проект не изменяется.</span><button id="review-edit">Редактировать копию</button>';document.body.append(reviewBanner);
document.querySelector('#review-edit').onclick=()=>{try{const previous=localStorage.getItem(AUTOSAVE);if(previous){const list=library();if(list.length>=20){toast('В «Моих проектах» уже 20 копий. Освободите место для резервной копии.');return;}const backup=parseProject(previous);backup.name='До открытия снимка · '+backup.name;list.unshift({id:createModule('base').id,date:new Date().toISOString(),data:JSON.stringify(backup)});localStorage.setItem(LIBRARY,JSON.stringify(list));}}catch{toast('Не удалось создать резервную копию. Сначала скачайте рабочий проект.');return;}reviewMode=false;document.body.dataset.reviewReadonly='false';reviewBanner.hidden=true;window.history.replaceState(null,'',location.pathname+location.search);history=new History(project);mode('orbit');renderHistory();autosave();toast('Копия открыта для редактирования');};
const allowedReview='#workflow button,#upgrade-inspect,#upgrade-inspect-exit,#node-scope,#node-all,#node-prev,#node-next,#opening-run,#opening-static,.disassembly-view-options summary,#opening-cancel,#opening-close,[data-opening-result],#disassembly-level,#disassembly-guides,#disassemble-open,#disassembly-play,#disassembly-assemble,#disassembly-exit,#disassembly-amount,#disassembly-layout,#disassembly-fit,#part-search,#part-category,[data-easy-part],#expert-toggle,#part-focus,#photo-view,#realism-toggle,#review-edit,#business-open,#export-open,#export-json,#export-csv,#export-obj,#export-png,#copy-brief,#screenshot,#fit-scene,#zoom-in,#zoom-out,#fullscreen,#help-open,#mobile-library,#mobile-inspector,#mobile-scene,.close-panel,.dialog-close,[data-view],[data-left],[data-inspector],[data-select],#focus-object,#estimate-module,[data-tab],[data-close],#pdf-download,#catalog-export,#catalog-template,[data-compare],#review-link,#review-copy,#review-url,#brief';
for(const event of ['click','input','change','contextmenu'])document.addEventListener(event,e=>{if(!reviewMode)return;if(e.target.closest('canvas')&&event!=='contextmenu')return;if(e.target.closest(allowedReview))return;if(e.target.closest('button,input,textarea,select,summary')||event==='contextmenu'){e.preventDefault();e.stopImmediatePropagation();if(event==='click')toast('Это снимок для просмотра. Для изменений откройте копию.');}},true);
if(reviewMode){mode('orbit');$('#save-state').textContent='Просмотр снимка · без автосохранения';}if(reviewError)toast('Ссылка просмотра: '+reviewError);
